/// <summary>
/// DebuC 16.06.23
/// </summary>
class NDXItemScopeHistory
{
    ItemId          itemId;
    InventSiteId    inventSiteId;

    Qty             PhysScope;
    Qty             PhysOnHand;
    Qty             AvailScope;
    Qty             AvailOnHand;
    yr              curYear;
    QtyAverage      ConsumpCurMonth;
    QtyAverage      ConsumpMedian;
    QtyAverage      ConsumpCurMonthInventSite;
    Qty             PhysScopeInventSite;
    Qty             AvailScopeInventSite;

}

