/// <summary>
/// DebuC 16.06.23
/// </summary>
/// <returns>container</returns>
container setCurrentValues()
{
    InventDimParm           inventDimParm;
    InventDim               inventDim;
    KCS_ItemScopeHistory    scopeHistory;
    InventOnhand            inventOnHand;
    container               conRet = connull();        
    NDX_ItemScopeHistoryInventSite    scopeHistoryInventSite;
    date                    curdate = endmth(prevmth(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone())));
    date                    minDate = Global::dateMthFwd(curdate,-13);
    Qty                     ConsumpAverageInventSite;
    KCS_ItemScopeHistory    lScopeHistory;        
    ;
    if (!itemId)
    {
        Error("@NDX:NDXItemScopeMissingItemId");
        return conRet;
    }
    if (!inventSiteId)
    {
        Error(strfmt("@NDX:NDXItemScopeMissingInventSiteId", itemId));       
        return conRet;
    }

    scopeHistory    = KCS_ItemScopeHistory::find(itemId, curYear, mthofyr(DateTimeUtil::date(DateTimeUtil::getSystemDateTime())));
    ConsumpCurMonth = (-1) * scopeHistory.ConsumpAverage;

    select sum(ConsumpSum) from scopeHistoryInventSite
    join lScopeHistory where lScopeHistory.RecId == scopeHistoryInventSite.RefRecId
                        && lScopeHistory.ItemId == itemId
                        && lScopeHistory.HistoryDate <= curdate
                        && lScopeHistory.HistoryDate >= minDate
                        && scopeHistoryInventSite.InventSiteId == inventSiteId;

    ConsumpAverageInventSite = scopeHistoryInventSite.ConsumpSum / 12.5;
    ConsumpCurMonthInventSite   = (-1) * ConsumpAverageInventSite;        

    ConsumpMedian   = (-1) * KCS_ItemScopeHistory::ItemMedianPerDate(itemId);

    // Bestand auf Standort-Ebene
    inventDim.InventSiteId  = inventSiteId;
    inventDimParm.initFromInventDim(inventDim);
    inventOnHand    = inventOnHand::newParameters(itemId, inventDim, inventDimParm);
    PhysOnHand      = inventOnHand.physicalInvent();

    AvailOnHand     = inventOnHand.availECP();

    if (!scopeHistory.ConsumpAverage || ReqGroup::find(inventTable::find(itemId).ReqGroupId).CovRule == ReqCovType::Req)
    {
        PhysScope   = 0;
        AvailScope  = 0;
    }
    else
    {
        PhysScope   = PhysOnHand / abs(scopeHistory.ConsumpAverage);
        AvailScope  = AvailOnHand / abs(scopeHistory.ConsumpAverage);
    }        
    if (!ConsumpAverageInventSite || ReqGroup::find(inventTable::find(itemId).ReqGroupId).CovRule == ReqCovType::Req)
    {
        PhysScope   = 0;
        AvailScope  = 0;            
        PhysScopeInventSite   = 0;
        AvailScopeInventSite  = 0;            
    }
    else
    {
        PhysScopeInventSite   = PhysOnHand / abs(ConsumpAverageInventSite);
        AvailScopeInventSite  = AvailOnHand / abs(ConsumpAverageInventSite);
    }        
    conRet += ConsumpCurMonth;
    conRet += ConsumpMedian;
    conRet += PhysOnHand;
    conRet += AvailOnHand;
    conRet += PhysScope;
    conRet += AvailScope;        
    conRet += ConsumpCurMonthInventSite;
    conRet += PhysScopeInventSite;
    conRet += AvailScopeInventSite;        

    return conRet;
}

public static NDXItemScopeHistory construct()
{
    NDXItemScopeHistory itemScopeHistory = new NDXItemScopeHistory();

    return itemScopeHistory;
}
